import numpy as np

def build_features(splits, meta):
    def _abs_time(d):
        d = np.asarray(d)
        if np.issubdtype(d.dtype, np.number):
            return d.astype(np.int64, copy=False)
        # robust fallback for string/object dates
        uniq, inv = np.unique(d.astype(str), return_inverse=True)
        return inv.astype(np.int64)

    def _build_one(split):
        user = np.asarray(split['user'])
        tab = np.asarray(split['tab'])
        date = _abs_time(split['date'])
        time_ms = np.asarray(split['time_ms']).astype(np.int64, copy=False)
        n = len(user)

        # Stable chronological order within split; tie-break by original index.
        idx = np.arange(n, dtype=np.int64)
        order = np.lexsort((idx, time_ms, date, user))

        gap_impr = np.full(n, np.nan, dtype=np.float32)
        gap_ms = np.full(n, np.nan, dtype=np.float32)
        prev_same = np.full(n, np.nan, dtype=np.float32)

        last_ut_pos = {}
        last_ut_time = {}
        last_u_tab = {}

        for pos, i in enumerate(order):
            u = int(user[i])
            t = int(tab[i])
            now = int(date[i]) * 86400000 + int(time_ms[i])
            key = (u, t)

            if key in last_ut_pos:
                gap_impr[i] = float(pos - last_ut_pos[key])
                gap_ms[i] = float(now - last_ut_time[key])
            if u in last_u_tab:
                prev_same[i] = 1.0 if last_u_tab[u] == t else 0.0

            last_ut_pos[key] = pos
            last_ut_time[key] = now
            last_u_tab[u] = t

        # compress heavy-tailed gaps
        gap_impr = np.log1p(gap_impr)
        gap_ms = np.log1p(np.maximum(gap_ms, 0))
        return {
            'user_recent_tab_reengagement_gap_impr': gap_impr.astype(np.float32),
            'user_recent_tab_reengagement_gap_ms': gap_ms.astype(np.float32),
            'user_prev_same_tab': prev_same.astype(np.float32),
        }

    per_split = {name: _build_one(split) for name, split in splits.items()}
    feat_names = list(next(iter(per_split.values())).keys())
    out = {f: {} for f in feat_names}
    for split_name, feats in per_split.items():
        for f, arr in feats.items():
            out[f][split_name] = arr
    return out
